const menu = document.querySelector('.menu');
const navigation = document.querySelector('#navigation');
menu.addEventListener('click', () => { const open = menu.getAttribute('aria-expanded') !== 'true'; menu.setAttribute('aria-expanded', String(open)); menu.setAttribute('aria-label', open ? 'Close navigation' : 'Open navigation'); navigation.classList.toggle('open', open); });
navigation.addEventListener('click', e => { if (e.target.closest('a')) { menu.setAttribute('aria-expanded', 'false'); menu.setAttribute('aria-label', 'Open navigation'); navigation.classList.remove('open'); } });
document.addEventListener('keydown', e => { if (e.key === 'Escape' && navigation.classList.contains('open')) { menu.click(); menu.focus(); } });
const industries = {
 energy: {name:'Energy & utilities',title:'Keep the world<br>moving forward.',description:'From the generation fleet to the grid, connect performance, maintenance, and field knowledge to make more informed operational decisions.',image:'wind.jpg',alt:'Wind turbines silhouetted against a warm sunset',points:['Asset reliability & maintenance','Generation performance','Connected field operations']},
 manufacturing: {name:'Process manufacturing',title:'Clarity at every<br>stage of production.',description:'Connect production signals with equipment and process knowledge. Give engineers the context to investigate variation and plan maintenance around the work.',image:'refinery.jpg',alt:'Industrial process towers and interconnected pipework',points:['Process visibility & troubleshooting','Production quality & consistency','Maintenance planning']},
 mining: {name:'Metals & mining',title:'A deeper view.<br>A stronger operation.',description:'Bring the pit, the plant, and the fleet into one operational picture. Understand the constraints that shape throughput, reliability, and resource use.',image:'quarry.jpg',alt:'Terraced open-pit mine seen from above',points:['Equipment & fleet reliability','Mine-to-mill visibility','Resource & energy performance']}
};
const tabs = [...document.querySelectorAll('[data-industry]')];
function selectIndustry(tab) { const data = industries[tab.dataset.industry]; tabs.forEach(t => { t.setAttribute('aria-selected', String(t === tab)); t.tabIndex = t === tab ? 0 : -1; }); document.querySelector('#industry-panel').setAttribute('aria-labelledby', tab.id); document.querySelector('#industry-name').textContent = data.name; document.querySelector('#industry-title').innerHTML = data.title; document.querySelector('#industry-description').textContent = data.description; const img = document.querySelector('#industry-image'); img.src = `assets/${data.image}`; img.alt = data.alt; document.querySelector('#industry-points').replaceChildren(...data.points.map(point => { const li = document.createElement('li'); li.textContent = point; return li; })); }
tabs.forEach((tab, i) => { tab.addEventListener('click', () => selectIndustry(tab)); tab.addEventListener('keydown', e => { let index; if (e.key === 'ArrowRight') index = (i + 1) % tabs.length; if (e.key === 'ArrowLeft') index = (i - 1 + tabs.length) % tabs.length; if (e.key === 'Home') index = 0; if (e.key === 'End') index = tabs.length - 1; if (index !== undefined) { e.preventDefault(); tabs[index].focus(); selectIndustry(tabs[index]); } }); });
const assets = {
 pump: {title:'Cooling water pump',location:'Process unit B / Cooling system',status:'Review required',label:'Vibration',value:'7.2 <small>mm/s</small>',state:'Running',inspection:'12 days ago',evidence:'Vibration has increased over the past 48 hours. The last work order recorded bearing wear on the drive end.',next:'Schedule a bearing inspection during the next planned maintenance window. Confirm operating conditions before changing the schedule.'},
 turbine: {title:'Gas turbine',location:'Power island / Generation train 1',status:'Within range',label:'Exhaust temp.',value:'512 <small>°C</small>',state:'Running',inspection:'3 days ago',evidence:'Exhaust temperature is within the illustrative operating range. The latest inspection recorded no new anomalies.',next:'Continue routine monitoring. Review the next scheduled inspection with the maintenance team.'},
 conveyor: {title:'Primary conveyor',location:'Materials handling / Transfer line 3',status:'Inspection due',label:'Belt speed',value:'2.4 <small>m/s</small>',state:'Running',inspection:'28 days ago',evidence:'The planned inspection interval is approaching. The maintenance log notes previous belt tracking adjustments.',next:'Inspect belt alignment and idler condition at the next planned stop. Record findings in the maintenance log.'}
};
let currentAsset = 'pump'; const reviewed = new Set(); const reviewButton = document.querySelector('#review-button');
function updateReview() { const done = reviewed.has(currentAsset); reviewButton.textContent = done ? 'Reviewed' : 'Mark as reviewed'; reviewButton.disabled = done; document.querySelector('#review-status').textContent = done ? 'Saved for this demo session.' : ''; }
document.querySelectorAll('[data-asset]').forEach(button => button.addEventListener('click', () => { currentAsset = button.dataset.asset; const a = assets[currentAsset]; document.querySelectorAll('[data-asset]').forEach(b => { b.classList.toggle('selected', b === button); b.setAttribute('aria-pressed', String(b === button)); }); for (const [id,value] of Object.entries({'asset-title':a.title,'asset-location':a.location,'asset-status':a.status,'reading-label':a.label,'operating-value':a.state,'inspection-value':a.inspection,'asset-evidence':a.evidence,'asset-next':a.next})) document.getElementById(id).textContent = value; document.querySelector('#reading-value').innerHTML = a.value; updateReview(); }));
reviewButton.addEventListener('click', () => { reviewed.add(currentAsset); updateReview(); });
const reelItems = [
 {image:'refinery.jpg',alt:'Expansive refinery infrastructure under a dramatic sky',title:'A clearer view of<br>everything that matters.',link:'Explore connected operations'},
 {image:'wind.jpg',alt:'Wind turbines capturing energy at sunset',title:'Powering a more<br>resilient tomorrow.',link:'Explore energy operations'},
 {image:'quarry.jpg',alt:'Aerial view of an expansive terraced mine',title:'From deeper insight.<br>To better decisions.',link:'Explore mining operations'}
];
let reelIndex = 0; const reelTabs = [...document.querySelectorAll('[data-reel]')];
function selectReel(index) { reelIndex = (index + reelItems.length) % reelItems.length; const item = reelItems[reelIndex]; const image = document.querySelector('#reel-image'); image.src = `assets/${item.image}`; image.alt = item.alt; document.querySelector('#reel-title').innerHTML = item.title; document.querySelector('#reel-link').textContent = item.link; document.querySelector('#reel-count').textContent = `0${reelIndex + 1} / 03`; document.querySelector('#reel-panel').setAttribute('aria-labelledby', `reel-tab-${reelIndex}`); reelTabs.forEach((tab,i) => { tab.setAttribute('aria-selected',String(i === reelIndex)); tab.tabIndex = i === reelIndex ? 0 : -1; }); }
reelTabs.forEach((tab,index) => {tab.addEventListener('click',() => selectReel(index)); tab.addEventListener('keydown',e => {let next; if(e.key==='ArrowRight')next=(index+1)%3; if(e.key==='ArrowLeft')next=(index+2)%3; if(e.key==='Home')next=0; if(e.key==='End')next=2; if(next!==undefined){e.preventDefault();selectReel(next);reelTabs[next].focus();}});});
document.querySelector('#reel-prev').addEventListener('click',()=>selectReel(reelIndex-1));document.querySelector('#reel-next').addEventListener('click',()=>selectReel(reelIndex+1));
